'use strict';
const L=StudyLogic,KEY='qishang-study-v1',PREF='qishang-preferences-v1';let bank=[],state=L.fresh(),view='home',prefs={excluded:[]},f={subject:'',chapter:'',type:'',pool:'all',unanswered:false,point:''},wrongTab='wrong',draft=null,shortRevealed=false;let gridOpen=false,analysisSubject='地理',apiStatus={aiConfigured:false,storage:'local'},apiChecked=false,ai={pending:false,error:'',result:null,controller:null};const sync={mode:'local',revision:0,ready:false,initialized:false,loading:false,saving:false,pending:null,error:'',blocked:false,needsChoice:false,localCandidate:null};const main=document.getElementById('main');const requireServer=document.querySelector?.('meta[name="study-storage"]')?.content==='required';const allowInsecureHttpPackage=document.querySelector?.('meta[name="study-allow-insecure-http"]')?.content==='true';const apiURL=path=>new URL('api/'+path.replace(/^\/?api\//,''),document.baseURI).href;const auth={generation:0,required:false,needsLogin:false,busy:false,error:'',pendingRecovery:null,recovery:null};let serverError='';
const LEARNING_QUOTES=[{"id":"luyu-practice","text":"纸上得来终觉浅，绝知此事要躬行。","author":"陆游","source":"《冬夜读书示子聿》","url":"https://www.xinhuanet.com/politics/2016-08/25/c_129254852.htm"},{"id":"kongzi-thinking","text":"学而不思则罔，思而不学则殆。","author":"孔子","source":"《论语·为政》","url":"https://m.ccdi.gov.cn/content/56/7a/3777.html"},{"id":"kongzi-review","text":"温故而知新，可以为师矣。","author":"孔子","source":"《论语·为政》","url":"https://jw.beijing.gov.cn/language/ywsh/201612/t20161219_1056478.html"},{"id":"xunzi-small-steps","text":"不积跬步，无以至千里。","author":"荀子","source":"《荀子·劝学》","url":"https://www.sdcourt.gov.cn/jningzcfy/386537/386541/6156975/index.html"},{"id":"xunzi-persistence","text":"锲而不舍，金石可镂。","author":"荀子","source":"《荀子·劝学》","url":"https://www.ccdi.gov.cn/specialn/lswhyl/wqhglswhyl/202112/t20211230_161237.html"},{"id":"zhuxi-reading","text":"问渠那得清如许？为有源头活水来。","author":"朱熹","source":"《观书有感·其一》","url":"https://www.shidianguji.com/mingju/7624424286379982888"},{"id":"hanyu-diligence","text":"业精于勤，荒于嬉；行成于思，毁于随。","author":"韩愈","source":"《进学解》","url":"https://www.gushiwen.cn/GuShiWen_6ad9003739.aspx"},{"id":"dufu-reading","text":"读书破万卷，下笔如有神。","author":"杜甫","source":"《奉赠韦左丞丈二十二韵》","url":"https://wwj.beijing.gov.cn/bjww/resource/cms/article/362762/515610/2018071114331575842.pdf"},{"id":"laozi-first-step","text":"千里之行，始于足下。","author":"老子","source":"《老子·第六十四章》","url":"https://www.moe.gov.cn/jyb_xwfb/moe_2082/2025/2025_zl02/202510/t20251009_1416036.html"},{"id":"sushi-accumulation","text":"博观而约取，厚积而薄发。","author":"苏轼","source":"《稼说送张琥》","url":"https://news.cufe.edu.cn/__local/E/E7/8F/76650C441C7F00C2CD8E20D440C_C08C7E02_CD7A7.pdf"}];const QUOTE_KEY='mingxuan-quote-last-v1';let currentQuote=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const types={choice:'选择题',fill:'填空题',short:'简答题'};const subjects=()=>[...new Set(bank.map(q=>q.subject))];const rec=id=>state.records[id]||{};const chapterKey=q=>q.subject+'｜'+q.chapter;const allowed=q=>!prefs.excluded.includes(chapterKey(q));const eligible=()=>bank.filter(allowed);const selected=()=>L.filter(eligible(),state,f).filter(q=>!f.point||q.point===f.point);const answered=()=>Object.values(state.records).filter(r=>r.attempts>0).length;
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));queueSync();return true}catch(e){document.getElementById('storage-warning').hidden=false;document.getElementById('storage-warning').textContent='浏览器未能保存进度，请保持页面打开，并导出备份。';queueSync();return false}}
function savePrefs(){try{localStorage.setItem(PREF,JSON.stringify(prefs))}catch(e){toast('学习范围未能保存，请检查浏览器存储权限。')}queueSync();}
function stats(){let attempts=0,correct=0,wrong=0,favorites=0,mastered=0;Object.values(state.records).forEach(r=>{attempts+=r.attempts||0;correct+=r.correct||0;if(r.everWrong){if(r.mastered)mastered++;else wrong++}if(r.favorite)favorites++});return{attempts,correct,wrong,favorites,mastered,accuracy:attempts?Math.round(100*correct/attempts):null}}
function header(title,subtitle,eyebrow='YOUR STUDY SPACE'){return `<header class="topline"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><div class="subtle">${subtitle}</div></div><div class="date-pill">七年级上册 · 自主练习</div></header>`}
function statCards(){const s=stats();return `<div class="stats"><div class="stat"><label>已练习题目</label><strong>${answered()}</strong><small>/ ${bank.length} 题</small></div><div class="stat"><label>累计作答正确率</label><strong>${s.accuracy??'—'}</strong><small>${s.accuracy===null?'待开始':'%'}</small></div><div class="stat"><label>待复习错题</label><strong>${s.wrong}</strong><small>题</small></div><div class="stat"><label>我的收藏</label><strong>${s.favorites}</strong><small>题</small></div></div>`}
function navigate(v){if(v==='home'&&view!=='home')rotateQuote();view=v;draft=null;shortRevealed=false;render();window.scrollTo(0,0)}
function render(){transportNotice();if(auth.needsLogin){loginGate();return;}if(auth.recovery){recoveryGate();return;}if(requireServer&&(serverError||sync.error||(!sync.ready&&!sync.loading&&!sync.needsChoice&&apiChecked))){serverGate();return;}if(sync.loading){main.innerHTML='<div class="loading" role="status">正在读取部署数据库，请稍候…</div>';return;}if(sync.needsChoice){syncGate();return}const s=stats();document.getElementById('nav-wrong').textContent=s.wrong;document.getElementById('nav-fav').textContent=s.favorites;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view||(view==='question'&&x.dataset.view==='practice')));if(view==='home')home();else if(view==='question')question();else if(view==='summary')summary();else if(view==='help')help();else if(view==='diagnostic')diagnostic();else if(view==='analysis')analysis();else setup();}
function rotateQuote(){let last=currentQuote?LEARNING_QUOTES.findIndex(q=>q.id===currentQuote.id):-1;try{const saved=localStorage.getItem(QUOTE_KEY);const stored=LEARNING_QUOTES.findIndex(q=>q.id===saved);if(stored>=0)last=stored;}catch(e){}currentQuote=LEARNING_QUOTES[L.pickQuoteIndex(LEARNING_QUOTES.length,last)];try{localStorage.setItem(QUOTE_KEY,currentQuote.id);}catch(e){}}
function homeQuote(){if(!currentQuote)rotateQuote();return `<section class="home-quote" aria-label="今日寄语"><p><span>“${esc(currentQuote.text)}”</span><cite>— <a href="${esc(currentQuote.url)}" target="_blank" rel="noopener noreferrer" title="${esc(currentQuote.source)} · 点击查看引用来源">${esc(currentQuote.author)}</a></cite></p></section>`;}
function home(){const resume=state.session&&state.session.ids.length?`<div class="resume"><div><strong>上次的练习，还在这里</strong><p>已完成 ${Object.keys(state.session.answers).length} / ${state.session.ids.length} 题 · 支持随时继续</p></div><button class="secondary" data-action="resume">继续练习 →</button></div>`:'';main.innerHTML=homeQuote()+`<div class="home-actions"><button class="primary" data-view="practice">开始练习 →</button><button class="secondary" data-view="help">已学单元与设置</button></div>`+resume+statCards()+`<div class="section-heading"><h2>选择你的学习科目</h2><button class="text-button" data-view="help">设置已学单元 ↗</button></div><div class="subject-grid">${subjects().map((s,i)=>{const qs=bank.filter(q=>q.subject===s),n=qs.filter(q=>rec(q.id).attempts).length;return `<article class="subject-card ${i%2?'geo':''}"><div class="subject-head"><div class="subject-icon" aria-hidden="true">${{'地理':'◎','生物':'❧','数学':'∑','语文':'文','英语':'Aa'}[s]||'◇'}</div><div><h3>${esc(s)}</h3><span class="subtle">${new Set(qs.map(q=>q.chapter)).size} 个单元 · ${new Set(qs.map(q=>q.point)).size} 个知识点 · ${qs.length} 题（含巩固变式）</span></div></div><div class="bar"><i style="width:${100*n/qs.length}%"></i></div><div class="subject-foot"><span>已练 ${n} 题 · ${Math.round(100*n/qs.length)}%</span><button data-subject="${esc(s)}">进入练习 →</button></div></article>`}).join('')}</div><div class="section-heading"><h2>不只看分数，也看知识点</h2><button class="secondary" data-view="diagnostic">查看知识点诊断 →</button></div><div class="tip">学习提醒：不同教材和学校进度会有差异。请先在「已学单元」中设置范围；题库是原创辅助练习，不是官方试题库或考试范围承诺。</div>`;}
function filterHTML(){const chapters=[...new Set(eligible().filter(q=>!f.subject||q.subject===f.subject).map(q=>q.chapter))];return `<div class="filters"><div class="field"><label for="subject">科目</label><select id="subject" data-filter="subject"><option value="">全部科目</option>${subjects().map(x=>`<option ${x===f.subject?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label for="chapter">单元 / 章节</label><select id="chapter" data-filter="chapter"><option value="">全部已学单元</option>${chapters.map(x=>`<option ${x===f.chapter?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label for="type">题型</label><select id="type" data-filter="type"><option value="">全部题型</option>${Object.entries(types).map(([k,v])=>`<option value="${k}" ${k===f.type?'selected':''}>${v}</option>`).join('')}</select></div></div>${f.point?`<div class="tip">知识点：${esc(f.point)} <button data-action="clear-point">清除知识点筛选</button></div>`:''}`}
function setup(){f.pool=view==='wrong'?wrongTab:view==='favorites'?'favorites':'all';const qs=selected();const title=view==='wrong'?'错题本':view==='favorites'?'收藏夹':'开始刷题';const desc=view==='wrong'?'错题历史一直保留。连续答对 2 次，自动移入「已巩固」。':view==='favorites'?'把值得回看的题留下来，随时再练一次。':'选择已学单元和题型，按照自己的节奏来。';main.innerHTML=header(title,desc,'PRACTICE, AT YOUR PACE')+(view==='wrong'?`<div class="tabs">${[['wrong','待复习'],['mastered','已巩固'],['history','全部错题历史']].map(([k,v])=>`<button class="${wrongTab===k?'active':''}" data-tab="${k}">${v} · ${L.filter(bank,state,{pool:k}).length}</button>`).join('')}</div>`:'')+`<section class="panel">${filterHTML()}<div class="filter-actions"><label><input type="checkbox" data-filter="unanswered" ${f.unanswered?'checked':''}>只练未答过的题</label><span class="subtle">当前范围 ${qs.length} 题</span><button class="primary" data-action="start" ${!qs.length?'disabled':''}>顺序练习 →</button><button class="secondary" data-action="random" ${!qs.length?'disabled':''}>随机练习</button></div></section><div class="tip">当前仅包含已勾选的学习单元。<button class="text-button" data-view="help">调整已学单元与备份设置 →</button></div>${qs.length?`<section class="panel"><div class="section-heading" style="margin-top:0"><h2>题目预览</h2><span class="subtle">${qs.length} 题</span></div>${qs.slice(0,80).map(q=>listRow(q)).join('')}${qs.length>80?`<p class="subtle">仅预览前 80 题，开始练习会包含全部 ${qs.length} 题。</p>`:''}</section>`:empty(view==='wrong'?'这里暂时没有符合条件的错题':'没有符合条件的题目','试试调整科目、章节、题型或「只练未答过的题」。')}`;}
function listRow(q){const r=rec(q.id);return `<div class="list-row"><div><span class="badge">${esc(q.subject)}</span><span class="badge">${types[q.type]}</span>${r.everWrong?`<span class="badge ${r.mastered?'':'amber'}">${r.mastered?'已巩固':'待复习'} · 错 ${r.wrong} 次</span>`:''}<div class="stem-preview">${esc(q.stem)}</div><span class="subtle">${esc(q.chapter)} · ${esc(q.point)}</span></div><div class="list-actions"><button class="favorite ${r.favorite?'saved':''}" data-favorite="${esc(q.id)}">${r.favorite?'★ 已收藏':'☆ 收藏'}</button><button data-open="${esc(q.id)}">${r.attempts?'查看 / 再练':'练这道'}</button></div></div>`}
function empty(t,d){return `<section class="panel empty"><div class="empty-icon">◇</div><h2>${t}</h2><p>${d}</p><button class="secondary" data-view="home">回到学习概览</button></section>`}
function start(random=false,ids=null){const qs=ids||selected().map(q=>q.id);if(!qs.length)return;if(state.session&&Object.keys(state.session.answers).length<state.session.ids.length&&!confirm('开始新练习会替换当前练习进度，但答题记录、错题和收藏都会保留。继续吗？'))return;if(random)for(let i=qs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]]}state.session={ids:qs,index:0,answers:{},startedAt:Date.now()};save();navigate('question')}
function current(){return bank.find(q=>q.id===state.session?.ids[state.session.index])}
function answerText(q){return q.type==='choice'?`${'ABCD'[q.answer]}．${q.options[q.answer]}`:q.type==='fill'?q.answer.map((x,i)=>`第 ${i+1} 空：${x[0]}`).join('；'):q.answer}
function question(){if(!state.session||!current()){navigate('practice');return}const q=current(),session=state.session,saved=session.answers[q.id],r=rec(q.id);if(draft===null)draft=saved?.answer??(q.type==='fill'?q.answer.map(()=>''):q.type==='short'?'':null);main.innerHTML=header('专注这一题，就很好。',`${q.subject} · ${q.chapter}`,'ONE QUESTION AT A TIME')+`<div class="question-top"><div><span class="badge">${types[q.type]}</span><span class="badge">${esc(q.difficulty)}</span>${q.extension?'<span class="badge amber">拓展练习</span>':''}<span class="subtle">第 ${session.index+1} / ${session.ids.length} 题</span></div><button class="favorite ${r.favorite?'saved':''}" data-favorite="${q.id}">${r.favorite?'★ 已收藏':'☆ 收藏本题'}</button></div><div class="bar"><i style="width:${100*Object.keys(session.answers).length/session.ids.length}%"></i></div><article class="panel question-card"><h2>${esc(q.stem)}</h2>${q.svg||''}${q.type==='choice'?`<div class="options" role="group" aria-label="选择答案">${q.options.map((o,i)=>`<button class="option ${draft===i?'selected':''} ${saved&&i===q.answer?'correct':''} ${saved&&draft===i&&!saved.correct?'incorrect':''}" data-choice="${i}" aria-pressed="${draft===i}" ${saved?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join('')}</div>`:q.type==='fill'?q.answer.map((a,i)=>`<div class="fill-row"><label for="blank-${i}">第 ${i+1} 空</label><input type="text" id="blank-${i}" data-blank="${i}" value="${esc(draft[i]||'')}" autocomplete="off" maxlength="1000" ${saved?'disabled':''}></div>`).join(''):`<label class="subtle" for="short-answer">先写出自己的思路，再看参考答案（简答题由自己核对）</label><textarea id="short-answer" maxlength="20000" placeholder="写下关键词、步骤或完整答案…" ${saved||shortRevealed?'disabled':''}>${esc(draft)}</textarea>`}${saved?explanation(q,saved.correct):`<div class="answer-actions">${q.type==='short'?shortRevealed?'':`<button class="primary" data-action="reveal">写好了，查看参考答案</button>`:`<button class="primary" data-action="submit">提交答案</button>`}</div>${shortRevealed?explanation(q,null)+`<p class="subtle">这是自主核对，不是 AI 自动判分。对照关键词与要点，客观记录本次结果。</p><div class="answer-actions"><button class="primary" data-self="true">我答对了</button><button class="secondary" data-self="false">还需复习</button></div>`:''}`}${saved?`<div class="answer-actions"><span class="subtle">已记录本次作答；再次查看不会重复计次。</span><button class="secondary" data-action="retry">重新作答此题</button>${r.everWrong&&r.mastered?`<button class="secondary" data-review="${q.id}">标记仍需复习</button>`:''}</div>`:''}</article>${answerGrid()}<div class="question-nav sticky-question-nav"><button class="secondary" data-step="-1" ${session.index===0?'disabled':''}>← 上一题</button><button class="secondary" data-action="grid" aria-expanded="${gridOpen}">答题卡 · ${Object.keys(session.answers).length}/${session.ids.length}</button><button class="secondary" data-view="summary">本轮结果</button><button class="primary" data-step="1" ${session.index===session.ids.length-1?'disabled':''}>下一题 →</button><span class="nav-note">可直接翻页，未提交不会计为答错</span></div>`;}
function explanation(q,correct){return `<section class="explanation ${correct===false?'wrong':''}" aria-live="polite"><h3>${correct===null?'参考答案 · 请自主核对':correct?'✓ 答对了，继续保持':'再理解一次，就更熟悉了'}</h3><p><strong>${q.type==='short'?'参考要点':'正确答案'}：</strong>${esc(answerText(q))}</p>${q.type==='fill'&&state.session?.answers[q.id]?`<p>${q.answer.map((values,i)=>`第 ${i+1} 空：${values.some(v=>L.normalize(v,q)===L.normalize(state.session.answers[q.id].answer[i],q))?'✓':'✗'} 你的答案「${esc(state.session.answers[q.id].answer[i])}」；参考「${esc(values[0])}」`).join('<br>')}</p>`:''}<p>${esc(q.explanation)}</p><div class="knowledge"><strong>知识点</strong>　${esc(q.point)}<br><strong>所在章节</strong>　${esc(q.subject)} / ${esc(q.chapter)}${q.keywords?.length?`<br><strong>核对关键词</strong>　${esc(q.keywords.join('、'))}`:''}</div></section>`}
function submit(correct){const q=current();if(state.session.answers[q.id])return;if(q.type==='choice'&&draft===null){toast('先选择一个答案吧。');return}if(q.type==='fill'&&draft.some(x=>!String(x).trim())){toast('请填写每一空后再提交。');return}if(q.type!=='short')correct=L.grade(q,draft);L.record(state,q.id,correct,draft);state.session.answers[q.id]={answer:draft,correct};save();render()}
function summary(){const s=state.session;if(!s){navigate('home');return}const entries=Object.values(s.answers),right=entries.filter(a=>a.correct).length;main.innerHTML=header('每一次认真练习，都算数。','回看薄弱处，比追求刷题速度更有价值。','SESSION REVIEW')+`<section class="panel summary"><div class="empty-icon" style="font-size:42px">✧</div><h2>${entries.length===s.ids.length?'本轮练习完成':'先休息一下，也很好'}</h2><div class="stats"><div class="stat"><label>本轮已答</label><strong>${entries.length}</strong><small>/ ${s.ids.length}</small></div><div class="stat"><label>本轮答对</label><strong>${right}</strong><small>题</small></div><div class="stat"><label>本轮答错</label><strong>${entries.length-right}</strong><small>题</small></div><div class="stat"><label>已答题正确率</label><strong>${entries.length?Math.round(right/entries.length*100):'—'}</strong><small>%</small></div></div><p class="unanswered-note">还有 <strong>${s.ids.length-entries.length}</strong> 道未做题；未做题不算错题，也不计入正确率。</p><div class="answer-actions" style="justify-content:center">${entries.length<s.ids.length?'<button class="primary" data-action="resume-unanswered">继续未做题 →</button>':''}<button class="secondary" data-action="grid-summary">查看答题卡</button><button class="secondary" data-action="resume">返回本轮练习</button><button class="secondary" data-action="session-wrongs">再练本轮错题</button><button class="secondary" data-view="wrong">进入错题本</button></div><p class="subtle">重新作答同一道题会更新本轮结果；累计作答和错题历史会保留所有次数。</p></section>`}
function help(){const grouped=subjects().map(s=>`<details open><summary><strong>${esc(s)}</strong></summary>${[...new Set(bank.filter(q=>q.subject===s).map(chapterKey))].map(k=>`<label style="display:flex;gap:10px;align-items:center;min-height:48px;font-size:14px"><input type="checkbox" data-chapter-key="${esc(k)}" ${!prefs.excluded.includes(k)?'checked':''}>${esc(k.split('｜')[1])}</label>`).join('')}</details>`).join('');main.innerHTML=header('让练习，适合你的进度。','学习范围、数据备份与使用说明。','SETTINGS & NOTES')+`<div class="help-grid"><section class="panel"><h2>已学单元</h2><p>默认全选。请取消尚未学习的单元；练习、错题和收藏的练习列表都会遵守此范围，不删除任何历史。</p><div class="data-actions"><button data-scope="all">全部选中</button><button data-scope="none">全部取消</button></div>${grouped}</section><div><section class="panel"><h2>进度与备份</h2>${auth.required?'<button class="secondary" data-action="logout">退出家庭学习空间</button>':''}<p>${sync.mode==='sqlite'?'独立部署模式：答题记录保存在当前服务器的 SQLite 数据库，并保留本浏览器备份。此部署是一份共享进度，不是多用户账号系统；不同设备访问同一服务器会使用同一份记录。':'浏览器模式：答题记录只保存在当前浏览器，不自动跨设备同步。更换设备、清理浏览器或隐私模式可能导致记录丢失。'}仅在主动请求 AI 分析时发送知识点汇总，不发送原始答案。定期导出备份最稳妥。</p><div class="data-actions"><button class="primary" data-action="export">导出进度 JSON</button><button class="secondary" data-action="import">导入进度</button><input id="import-file" type="file" accept="application/json,.json" hidden><button class="danger" data-action="clear">清空学习记录</button></div><p>导入会校验格式，并在确认后替换本机记录；旧版本或不属于本题库的题目记录不会被添加。</p></section><section class="panel" style="margin-top:18px"><h2>题库与判分说明</h2><p>本题库按七年级上册常见知识内容编写原创练习，不是教材逐页配套、官方题库、历年真题或完整考试范围。不同教材版本、学校进度存在差异，以老师要求为准。</p><p>题目数量不等于独立考点数量：同一知识点包含多道题及不同数据、情境的巩固变式，用于反复练习和观察表现；这不表示教材逐页或全部考点已覆盖。各科卡片同时列出本题库的知识点数量。</p><p>选择题与填空题按预设答案核对；填空支持常见同义表述，但未必覆盖所有合理表达。简答题先作答，再按参考答案自主记录，不进行 AI 判分。</p><p>错题历史不会因答对而自动删除，连续两次答对自动标为「已巩固」，仍可重新标记待复习。收藏与错题状态互不影响。</p><div class="data-actions"><button class="secondary" data-view="diagnostic">知识点诊断</button><button class="secondary" data-action="print">打印题库与答案</button><button class="secondary" data-action="bank-export">下载完整题库 JSON</button><a class="small-link" href="sources.txt" target="_blank" rel="noopener">查看参考资料说明 ↗</a></div></section></div></div>`}
function diagnostic(){const rows=L.diagnose(eligible(),state);main.innerHTML=header('找到值得多练的知识点。','五科知识点的轻量学习诊断，只统计已学单元。','KNOWLEDGE CHECK')+`<div class="tip">这不是正式能力评估。「未测」= 没作答；「待补测」= 少于 3 道不同题；「需巩固」= 已测至少 3 道不同题，且累计正确率低于 80% 或有题重复出错；「较稳」= 已测至少 3 题、正确率 ≥ 80% 且无重复错题。一次错误不能证明没有掌握，同一题反复作答也不增加覆盖题数。</div><div class="tabs">${['',...subjects()].map(s=>`<button data-diag-subject="${s}" class="${f.subject===s?'active':''}">${s||'全部五科'}</button>`).join('')}</div><section class="panel">${rows.filter(r=>!subjects().includes(f.subject)||r.subject===f.subject).map(r=>{const acc=r.accuracy,status=r.status;return `<div class="list-row"><div><span class="badge">${r.subject}</span><span class="badge ${status==='需巩固'?'amber':''}">${status}</span><h3>${esc(r.point)}</h3><div class="subtle">${esc(r.chapter)} · 覆盖 ${r.distinct} / ${r.total} 道不同题 · 累计作答正确率 ${acc===null?'—':acc+'%'} · 错误 ${r.wrong} 次 · 重复错题 ${r.repeated} 道</div>${r.distinct<3&&r.wrong>0?'<div class="low-evidence-warning">已有错题，样本不足</div>':''}${r.total<3?`<div class="subtle">当前题库该点仅 ${r.total} 题，重复刷同题不能补足诊断证据。</div>`:''}</div><button class="secondary" data-point="${esc(r.point)}" data-point-subject="${esc(r.subject)}" data-point-chapter="${esc(r.chapter)}">针对练习 →</button></div>`}).join('')||'<p class="subtle">当前已学范围内没有诊断题，请先调整已学单元。</p>'}</section>`}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printBank(){const qs=eligible();if(!qs.length){toast('请先选择已学单元。');return}const w=window.open('','_blank');if(!w){toast('请允许弹出窗口后重试。');return}w.document.write(`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>铭轩小站 · 题库与答案</title><style>body{font:15px/1.8 sans-serif;max-width:900px;margin:30px auto;padding:20px;color:#222}article{break-inside:avoid;border-bottom:1px solid #ccc;padding:15px 0}svg{max-width:100%;max-height:250px}h1{font-size:25px}.answers{break-before:page}button{padding:15px}@media print{button{display:none}}</style><button id="print-bank-button">打印 / 保存为 PDF</button><h1>七年级上册 · 原创辅助练习</h1><p>已选学习范围，共 ${qs.length} 题。非官方题库；教材与学校范围以教师要求为准。答案解析见后半部分。</p>${qs.map((q,i)=>`<article><strong>${i+1}. [${esc(q.subject)} · ${types[q.type]}] ${esc(q.stem)}</strong>${q.svg||''}${q.options?`<p>${q.options.map((o,j)=>`${'ABCD'[j]}. ${esc(o)}`).join('<br>')}</p>`:'<p>答：_________________________________________________</p>'}</article>`).join('')}<h1 class="answers">参考答案与知识点</h1>${qs.map((q,i)=>`<article><strong>${i+1}. ${esc(answerText(q))}</strong><p>${esc(q.explanation)}</p><small>${esc(q.subject)} / ${esc(q.chapter)} / ${esc(q.point)}</small></article>`).join('')}</html>`);w.document.close();w.document.getElementById('print-bank-button').addEventListener('click',()=>w.print());}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.view){e.preventDefault();if(['practice','wrong','favorites'].includes(el.dataset.view)){f.unanswered=false;f.point=''}navigate(el.dataset.view);return}if(el.dataset.subject){f={subject:el.dataset.subject,chapter:'',type:'',pool:'all',unanswered:false,point:''};navigate('practice');return}if(el.dataset.favorite){const id=el.dataset.favorite;state.records[id]={...rec(id),favorite:!rec(id).favorite};save();render();return}if(el.dataset.tab){wrongTab=el.dataset.tab;f.unanswered=false;render();return}if(el.dataset.open){const id=el.dataset.open;if(state.session&&state.session.ids.length&&!confirm('进入单题练习会替换当前练习进度，累计记录不变。继续吗？'))return;const r=rec(id);state.session={ids:[id],index:0,answers:r.attempts?{[id]:{answer:r.lastAnswer,correct:r.lastCorrect}}:{},startedAt:Date.now()};save();navigate('question');return}if(el.dataset.choice!==undefined){draft=Number(el.dataset.choice);question();return}if(el.dataset.self!==undefined){submit(el.dataset.self==='true');return}if(el.dataset.step){jumpTo(state.session.index+Number(el.dataset.step));return}if(el.dataset.jump!==undefined){jumpTo(Number(el.dataset.jump));return}if(el.dataset.review){const r=rec(el.dataset.review);r.mastered=false;r.consecutiveCorrect=0;save();render();toast('已移回待复习。');return}if(el.dataset.scope){prefs.excluded=el.dataset.scope==='all'?[]:[...new Set(bank.map(chapterKey))];savePrefs();render();return}if(el.dataset.analysisSubject!==undefined){analysisSubject=el.dataset.analysisSubject;render();return}if(el.dataset.diagSubject!==undefined){f.subject=el.dataset.diagSubject;render();return}if(el.dataset.point){f={subject:el.dataset.pointSubject,chapter:el.dataset.pointChapter||'',type:'',pool:'all',unanswered:false,point:el.dataset.point};navigate('practice');return}const a=el.dataset.action;if(a==='reload')location.reload();if(a==='login')login();if(a==='logout')logout();if(a==='retry-server'){if(sync.pending)auth.pendingRecovery=JSON.parse(JSON.stringify(sync.pending));sync.initialized=false;checkAPI().then(render)}if(a==='recovery-export')downloadRecovery();if(a==='recovery-server'){auth.recovery=null;sync.pending=null;render()}if(a==='recovery-local')restoreRecovery();if(a==='start'||a==='random')start(a==='random');if(a==='resume')navigate('question');if(a==='grid'){gridOpen=!gridOpen;render();if(gridOpen)document.getElementById('answer-grid-panel')?.scrollIntoView({block:'nearest',behavior:'smooth'})}if(a==='grid-summary'){gridOpen=true;navigate('question');document.getElementById('answer-grid-panel')?.scrollIntoView({block:'nearest'})}if(a==='resume-unanswered'){const i=state.session.ids.findIndex(id=>!state.session.answers[id]);if(i>=0)jumpTo(i)}if(a==='sync-import-local')chooseDatabase('import');if(a==='sync-fresh')chooseDatabase('fresh');if(a==='sync-browser')chooseDatabase('browser');if(a==='sync-retry'){sync.error='';flushSync()}if(a==='sync-reload'&&confirm('重新读取会用数据库记录替换本页尚未保存的改动，请先导出备份。继续吗？')){if(sync.saving){toast('正在保存，请等待完成后重新读取。');return;}if(sync.pending)auth.pendingRecovery=JSON.parse(JSON.stringify(sync.pending));sync.pending=null;initDatabase(true).then(()=>{document.getElementById('storage-warning').hidden=!sync.error;if(sync.ready&&auth.pendingRecovery){auth.recovery=auth.pendingRecovery;auth.pendingRecovery=null;}render()})}if(a==='analyze')runAnalysis();if(a==='cancel-ai')ai.controller?.abort();if(a==='check-api')checkAPI();if(a==='submit')submit();if(a==='reveal'){if(!String(draft).trim()){toast('先写下自己的答案或思路，再核对参考答案。');return}shortRevealed=true;render()}if(a==='retry'&&confirm('开始新的作答？本次会单独记录一次，历史不会删除。')){delete state.session.answers[current().id];draft=null;shortRevealed=false;save();render()}if(a==='next'){if(state.session.index<state.session.ids.length-1){state.session.index++;draft=null;shortRevealed=false;save();render();window.scrollTo(0,0)}else navigate('summary')}if(a==='session-wrongs'){const ids=Object.entries(state.session.answers).filter(([id,a])=>!a.correct).map(([id])=>id);if(ids.length)start(false,ids);else toast('本轮还没有错题。')}if(a==='clear-point'){f.point='';render()}if(a==='export'){download('铭轩小站-进度-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({...state,session:null,preferences:prefs,exportedAt:new Date().toISOString()},null,2));toast('备份已导出。')}if(a==='import')document.getElementById('import-file').click();if(a==='clear'&&confirm('确定清空所有答题记录、错题历史和收藏吗？此操作不可撤销，建议先导出备份。')){state=L.fresh();save();render();toast('学习记录已清空，已学单元设置保留。')}if(a==='print')printBank();if(a==='bank-export')download('铭轩小站-原创完整题库.json',JSON.stringify({title:'铭轩小站 · 原创辅助练习',scope:'非官方题库；教材与学校范围以教师要求为准。',questions:bank},null,2));});
document.addEventListener('input',e=>{if(e.target.dataset.blank!==undefined)draft[Number(e.target.dataset.blank)]=e.target.value;if(e.target.id==='short-answer')draft=e.target.value});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.filter){f[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;if(el.dataset.filter==='subject'){f.chapter='';f.point=''}render()}if(el.dataset.chapterKey){prefs.excluded=prefs.excluded.filter(k=>k!==el.dataset.chapterKey);if(!el.checked)prefs.excluded.push(el.dataset.chapterKey);savePrefs()}if(el.id==='import-file'&&el.files[0]){try{if(el.files[0].size>5000000)throw Error('备份文件过大');const input=JSON.parse(await el.files[0].text()),next=L.validate(input,bank);if(input.preferences&&(!Array.isArray(input.preferences.excluded)||!input.preferences.excluded.every(x=>typeof x==='string')))throw Error('已学单元设置无效');if(confirm(`已校验 ${Object.keys(next.records).length} 条题目记录。导入将替换当前进度、收藏和错题历史，继续吗？`)){state=next;if(input.preferences&&Array.isArray(input.preferences.excluded)&&input.preferences.excluded.every(x=>typeof x==='string')){prefs.excluded=input.preferences.excluded.filter(k=>bank.some(q=>chapterKey(q)===k));savePrefs()}save();render();toast('进度已导入。')}}catch(err){toast('导入失败：'+err.message)}}});
function jumpTo(index){if(!L.jump(state.session,index))return;draft=null;shortRevealed=false;save();navigate('question');}
function answerGrid(){const session=state.session,counts=L.sessionStats(session);return `<section id="answer-grid-panel" class="panel answer-grid-panel" ${gridOpen?'':'hidden'}><div class="section-heading" style="margin-top:0"><div><h2>本轮答题卡</h2><span class="subtle">点题号直接跳转，不需要先提交当前题</span></div><button class="secondary" data-action="grid">收起</button></div><div class="grid-legend"><span class="grid-state blank">未做 ${counts.unanswered}</span><span class="grid-state right">已答对 ${counts.correct}</span><span class="grid-state wrong">已答错 ${counts.wrong}</span><span class="grid-state current">外框 = 当前</span><span>★ = 收藏</span></div><div class="answer-grid">${session.ids.map((id,i)=>{const answer=session.answers[id],label=answer?answer.correct?'已答对':'已答错':'未做',favorite=rec(id).favorite;return `<button class="grid-number ${answer?answer.correct?'right':'wrong':'blank'} ${i===session.index?'current':''}" data-jump="${i}" aria-label="第 ${i+1} 题，${label}${i===session.index?'，当前题':''}${favorite?'，已收藏':''}" ${i===session.index?'aria-current="true"':''}><span>${i+1}</span>${favorite?'<small aria-hidden="true">★</small>':''}</button>`}).join('')}</div></section>`;}
const statusClass=status=>({'未测':'untested','待补测':'sparse','需巩固':'needs-work','较稳':'steady'}[status]||'untested');
function analysis(){const rows=L.diagnose(eligible(),state),shown=rows.filter(r=>!analysisSubject||r.subject===analysisSubject);main.innerHTML=header('把知识的脉络，看得更清楚。','先看本地知识图谱，再按需要请求 AI 给出学习建议。','KNOWLEDGE MAP & AI')+`<section class="panel analysis-intro"><div><span class="badge">本地知识图谱</span><h2>科目 → 章节 → 知识点</h2><p class="subtle">图谱结构来自题库标签，颜色来自真实作答记录；不依赖 AI，也不代表知识之间存在科学推断的因果关系。</p></div><div class="graph-legend">${['未测','待补测','需巩固','较稳'].map(x=>`<span class="point-status ${statusClass(x)}">${x} · ${rows.filter(r=>r.status===x).length}</span>`).join('')}</div></section><div class="graph-overview">${subjects().map(subject=>{const points=rows.filter(r=>r.subject===subject);return `<button class="subject-summary ${analysisSubject===subject?'selected':''}" data-analysis-subject="${esc(subject)}"><strong>${esc(subject)}</strong><span>已测 ${points.filter(r=>r.distinct).length}/${points.length} 个知识点</span><span>需巩固 ${points.filter(r=>r.status==='需巩固').length} · 待补测 ${points.filter(r=>r.status==='待补测').length}</span><small>历史错过 ${points.filter(r=>r.wrong>0).length} 个知识点</small></button>`}).join('')}</div><div class="tabs">${['',...subjects()].map(s=>`<button data-analysis-subject="${esc(s)}" class="${analysisSubject===s?'active':''}">${s||'全部五科'}</button>`).join('')}</div><div class="tip">仅显示已学单元。至少作答 3 道不同题后才显示「需巩固 / 较稳」；不足 3 题仍为「待补测」。颜色是复习线索，不是能力定论。点击知识点即可定向练习。</div>${shown.some(r=>r.wrong>0&&r.status!=='较稳')?`<section class="panel priority-points"><h3>优先复习线索</h3><p class="subtle">筛出历史错过、尚未显示「较稳」的知识点。低样本错误值得回看，但不等于没有掌握。</p><div class="priority-links">${shown.filter(r=>r.wrong>0&&r.status!=='较稳').sort((a,b)=>b.repeated-a.repeated||b.wrong-a.wrong).slice(0,12).map(r=>`<button class="secondary" data-point="${esc(r.point)}" data-point-subject="${esc(r.subject)}" data-point-chapter="${esc(r.chapter)}">${esc(r.point)}<small>${r.distinct<3?'已有错题，样本不足':r.status} · 错 ${r.wrong} 次</small></button>`).join('')}</div><p class="subtle">显示最多 12 个线索，完整记录见下方图谱与知识点诊断。</p></section>`:''}<section class="panel ai-panel"><div class="section-heading" style="margin-top:0"><div><span class="eyebrow">OPTIONAL · MODEL ANALYSIS</span><h2>AI 专项分析</h2></div><span class="badge ${apiStatus.aiConfigured?'':'amber'}">${!apiChecked?'正在检查服务':apiStatus.aiConfigured?'模型服务已配置':'模型服务未启用'}</span></div><p class="subtle">仅在你点击后发送当前已学范围的知识点汇总：科目、章节、知识点、覆盖题数、对错次数与诊断状态。不发送姓名、年龄、原始答案或完整作答记录。</p><p class="subtle">AI 建议可能不准确，请结合教材、老师要求和实际表现判断；本地图谱不使用模型生成的结论改变诊断颜色。</p>${!apiStatus.aiConfigured?'<div class="tip">当前可完整使用本地知识图谱。AI 服务尚未配置或当前是纯静态版本；这里不会用规则报告冒充 AI 结果。</div>':''}<div class="data-actions"><button class="primary" data-action="analyze" ${!apiStatus.aiConfigured||ai.pending||!rows.some(r=>r.distinct)?'disabled':''}>${ai.pending?'正在分析…':'请求 AI 分析已学知识点'}</button>${ai.pending?'<button class="secondary" data-action="cancel-ai">取消请求</button>':'<button class="secondary" data-action="check-api">重新检查服务</button>'}</div>${!rows.some(r=>r.distinct)?'<p class="subtle">先完成一些练习，积累记录后再请求分析。</p>':''}<p class="ai-state" role="status" aria-live="polite">${esc(ai.error|| (ai.pending?'已发送知识点汇总，可随时取消。':''))}</p>${ai.result?`<div class="ai-result"><h3>模型生成的学习建议</h3><div class="subtle">模型：${esc(ai.result.model||'未提供')} · ${esc(ai.result.generatedAt||'')}</div><div id="ai-output"></div></div>`:''}</section><div class="knowledge-tree">${subjects().filter(s=>!analysisSubject||s===analysisSubject).map(subject=>{const points=shown.filter(r=>r.subject===subject);if(!points.length)return '';const chapters=[...new Set(points.map(r=>r.chapter))];return `<section class="graph-subject"><div class="subject-root"><h2>${esc(subject)}</h2><span>${chapters.length} 章 · ${points.length} 个知识点</span><span>${points.filter(r=>r.status==='需巩固').length} 个需巩固 · ${points.filter(r=>r.status==='待补测').length} 个待补测</span></div><div class="chapter-branches">${chapters.map((chapter,chapterIndex)=>{const child=points.filter(r=>r.chapter===chapter);return `<details class="chapter-branch" ${analysisSubject&&chapterIndex===0?'open':''}><summary><strong>${esc(chapter)}</strong><span>${child.length} 个知识点</span></summary><div class="point-nodes">${child.map(r=>`<button class="point-node ${statusClass(r.status)}" data-point="${esc(r.point)}" data-point-subject="${esc(subject)}" data-point-chapter="${esc(chapter)}"><span class="point-status ${statusClass(r.status)}">${r.status}</span><strong>${esc(r.point)}</strong><span>覆盖 ${r.distinct}/${r.total} 题 · ${r.accuracy===null?'尚未作答':'累计正确率 '+r.accuracy+'%'}</span><small>错误 ${r.wrong} 次 · 重复错题 ${r.repeated} 道　↗</small>${r.distinct<3&&r.wrong>0?'<small class="low-evidence-warning">已有错题，样本不足</small>':''}${r.total<3?`<small>当前题库该点仅 ${r.total} 题，重复刷同题不能补足诊断证据。</small>`:''}</button>`).join('')}</div></details>`}).join('')}</div></section>`}).join('')||'<section class="panel empty">尚未选择学习单元，请在设置中调整。</section>'}</div>`;if(ai.result)document.getElementById('ai-output').textContent=ai.result.analysis;}
async function checkAPI(){const generation=auth.generation;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),6000);serverError='';try{const response=await fetch(apiURL('status'),{signal:controller.signal,cache:'no-store',credentials:'same-origin'});if(!response.ok)throw Error('服务不可用');const result=await response.json();if(generation!==auth.generation)return;if(!result||typeof result.aiConfigured!=='boolean'||!['sqlite','local'].includes(result.storage)||(requireServer&&result.storage!=='sqlite')||(result.authRequired===true&&typeof result.authenticated!=='boolean'))throw Error('服务器状态格式无效');if(allowInsecureHttpPackage&&new URL(document.baseURI).protocol==='http:'&&(!requireServer||result.insecurePublicHttp!==true||result.authRequired!==true||result.storage!=='sqlite'))throw Error('HTTP 部署未启用所需的共享数据库与访问保护');apiStatus=result;auth.required=result.authRequired===true;if(auth.required&&!result.authenticated){requireLogin();}else{auth.needsLogin=false;auth.error='';if(apiStatus.storage==='sqlite')await initDatabase(!sync.ready&&!sync.needsChoice);if(sync.ready&&auth.pendingRecovery){auth.recovery=auth.pendingRecovery;auth.pendingRecovery=null;}}}catch(e){if(generation!==auth.generation)return;apiStatus={aiConfigured:false,storage:requireServer?'sqlite':'local'};if(requireServer){serverError='未连接数据库，不能开始记录；请检查服务器后重试。';sync.ready=false;sync.blocked=true;}}finally{clearTimeout(timer);if(generation!==auth.generation)return;apiChecked=true;storageNotice();if(view==='analysis'||sync.needsChoice||requireServer||auth.needsLogin||auth.recovery)render();}}

async function runAnalysis(){const generation=auth.generation;if(ai.pending||!apiStatus.aiConfigured)return;const points=L.aggregate(eligible(),state);if(!points.some(r=>r.distinct)){toast('先完成练习，再请求分析。');return}const controller=new AbortController();let timedOut=false;ai={pending:true,error:'',result:null,controller};const run=ai;const timer=setTimeout(()=>{timedOut=true;controller.abort()},90000);render();try{const response=await fetch(apiURL('analyze'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({points}),signal:controller.signal});const result=await response.json().catch(()=>({}));if(generation!==auth.generation||ai!==run)return;if(response.status===401){requireLogin();throw Error('登录已过期，请重新登录。');}if(!response.ok)throw Error(result.error||result.message||`服务返回错误（${response.status}）`);if(typeof result.analysis!=='string'||!result.analysis.trim())throw Error('服务没有返回有效的分析内容');ai.result={analysis:result.analysis,model:String(result.model||''),generatedAt:String(result.generatedAt||'')};}catch(error){if(generation!==auth.generation||ai!==run)return;ai.error=error.name==='AbortError'?(timedOut?'分析请求已超时，请稍后重试。':'已取消分析请求。未生成 AI 结果。'):'分析未完成：'+error.message;}finally{clearTimeout(timer);if(generation!==auth.generation||ai!==run)return;ai.pending=false;ai.controller=null;if(view==='analysis'||auth.needsLogin)render();else toast(ai.result?'AI 分析已完成，可到专项分析查看。':ai.error);}}

function requireLogin(snapshot=null){auth.generation++;ai.controller?.abort();ai={pending:false,error:'',result:null,controller:null};auth.required=true;auth.needsLogin=true;auth.error='';if(snapshot||sync.pending)auth.pendingRecovery=JSON.parse(JSON.stringify(snapshot||sync.pending));sync.ready=false;sync.blocked=true;sync.loading=false;apiStatus.aiConfigured=false;render();}
function publicHttpOptIn(){return requireServer&&allowInsecureHttpPackage&&apiStatus.insecurePublicHttp===true&&apiStatus.authRequired===true&&apiStatus.storage==='sqlite';}
function transportNotice(){const url=new URL(document.baseURI),insecure=url.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(url.hostname);const notice=document.getElementById('transport-warning');if(notice){notice.hidden=!insecure;notice.textContent=insecure?'HTTP 明文连接：密码、会话与学习记录可能被窃听或篡改，请勿复用重要密码。':'';}document.body?.classList?.toggle('insecure-transport',insecure);}
function loginGate(){document.getElementById('nav-wrong').textContent='';document.getElementById('nav-fav').textContent='';document.getElementById('storage-warning').hidden=true;main.innerHTML=header('一家人的学习空间','同一份数据库进度，手机、平板和电脑共同使用。','FAMILY STUDY SPACE')+`<section class="panel login-panel"><div class="login-emblem" aria-hidden="true">⌘</div><h2>输入家庭访问密码</h2><p class="subtle">这是一个家庭共用的学习档案，不需要注册，也不是多个独立账号。密码仅用于访问保护。</p><form id="family-login-form"><label for="family-password">家庭访问密码</label><input id="family-password" type="password" maxlength="200" required autocomplete="current-password" ${auth.busy?'disabled':''}><button type="submit" class="primary" ${auth.busy?'disabled':''}>${auth.busy?'正在登录…':'进入学习空间 →'}</button></form><p class="ai-state" role="alert">${esc(auth.error)}</p>${auth.pendingRecovery?'<p class="tip">有尚未保存的本页进度。登录后会先读取数据库，再由你决定如何处理；不会自动覆盖数据库。</p>':''}<p class="subtle">访问密码不会保存在浏览器代码或学习备份中。${publicHttpOptIn()?'本部署明确启用了 HTTP 明文访问；请留意顶部风险提示。':'请通过 HTTPS 访问本页面。'}</p></section>`;}
function serverGate(){main.innerHTML=header('等待连接学习数据库','此部署必须使用服务器保存进度，不会退回浏览器缓存继续刷题。','DATABASE CONNECTION REQUIRED')+`<section class="panel"><h2>未连接数据库，不能开始记录</h2><p>${esc(serverError||sync.error||'数据库尚未就绪，请重试。')}</p><div class="data-actions">${sync.pending&&!sync.blocked?'<button class="primary" data-action="sync-retry">重试保存</button>':sync.pending?'<button class="primary" data-action="sync-reload">重新读取数据库并处理冲突</button>':'<button class="primary" data-action="retry-server">重试连接数据库</button>'}<button class="secondary" data-action="export">导出本页应急备份</button></div><p class="subtle">浏览器副本只用于应急导出，不是共享进度的来源。恢复连接后以数据库为准，任何替换都需要明确选择。</p></section>`;}
function recoveryGate(){main.innerHTML=header('数据库已连接，先处理待保存进度','其他设备可能已经更新了共享档案，请选择保留哪份。','RESOLVE UNSAVED CHANGES')+`<section class="panel"><h2>这页还有一份未同步的进度</h2><p>已读取数据库最新版本 ${sync.revision}。不会自动把本页旧进度写回；建议先导出备份，再决定是否替换。</p><div class="data-actions"><button class="primary" data-action="recovery-server">使用数据库最新进度</button><button class="secondary" data-action="recovery-export">导出待保存进度</button><button class="danger" data-action="recovery-local">用待保存进度替换数据库</button></div><p class="subtle">替换会覆盖其他设备当前已保存的记录；如果版本再次变化，服务器会拒绝并提示冲突。</p></section>`;}
function downloadRecovery(){const snapshot=auth.recovery||auth.pendingRecovery;if(snapshot)download('铭轩小站-未同步应急备份.json',JSON.stringify({...snapshot.state,preferences:snapshot.preferences},null,2));}
function restoreRecovery(){if(!auth.recovery||!confirm('确定用本页未同步进度替换数据库最新记录吗？这可能覆盖其他设备的新作答。建议先导出备份。'))return;state=restoreState(auth.recovery.state);prefs=validPrefs(auth.recovery.preferences);auth.recovery=null;sync.pending=null;sync.error='';sync.blocked=false;sync.ready=true;save();savePrefs();render();}
async function login(){if(auth.busy)return;const input=document.getElementById('family-password'),password=input?.value||'';if(!password||password.length>200){auth.error='请输入家庭访问密码（最多 200 个字符）。';render();return;}const url=new URL(document.baseURI);if(url.protocol!=='https:'&&!['localhost','127.0.0.1','[::1]'].includes(url.hostname)&&!(url.protocol==='http:'&&publicHttpOptIn())){auth.error='为保护密码，请通过 HTTPS 地址登录。';input.value='';render();return;}input.value='';auth.busy=true;auth.error='';render();try{const response=await apiFetch('login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const result=await response.json();if(!response.ok||result.authenticated!==true)throw Error(response.status===429?'尝试次数较多，请稍后重试。':'密码不正确或登录未成功，请重试。');auth.needsLogin=false;sync.initialized=false;sync.error='';serverError='';await checkAPI();}catch(e){auth.error=e.name==='AbortError'?'登录请求超时，请重试。':e.message;auth.needsLogin=true;}finally{auth.busy=false;render();}}
async function logout(){if(sync.saving){toast('正在保存，请等待完成后再退出。');return;}if((sync.pending||auth.recovery)&&!confirm('还有未同步进度。退出会清除本页临时记录，请先导出备份。仍然退出吗？'))return;try{const response=await apiFetch('logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok&&response.status!==401)throw Error('退出未成功，请检查连接后重试。');auth.generation++;ai.controller?.abort();ai={pending:false,error:'',result:null,controller:null};state=L.fresh();prefs={excluded:[]};draft=null;shortRevealed=false;gridOpen=false;view='home';sync.pending=null;sync.ready=false;sync.loading=false;sync.initialized=false;sync.blocked=true;sync.needsChoice=false;sync.localCandidate=null;sync.error='';auth.pendingRecovery=null;auth.recovery=null;auth.needsLogin=true;auth.error='';try{localStorage.removeItem(KEY);localStorage.removeItem(PREF);}catch(e){}render();}catch(e){toast(e.message);}}
document.addEventListener('submit',event=>{if(event.target.id==='family-login-form'){event.preventDefault();login();}});

function restoreState(input){const restored=L.validate(input,bank),s=input.session;if(s&&Array.isArray(s.ids)&&s.ids.length&&new Set(s.ids).size===s.ids.length&&s.ids.every(id=>bank.some(q=>q.id===id))&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.ids.length&&s.answers&&typeof s.answers==='object'&&!Array.isArray(s.answers)){const answers={};for(const [id,a]of Object.entries(s.answers)){const q=bank.find(q=>q.id===id);if(s.ids.includes(id)&&a&&typeof a.correct==='boolean'&&q&&((q.type==='choice'&&Number.isInteger(a.answer)&&a.answer>=0&&a.answer<q.options.length)||(q.type==='fill'&&Array.isArray(a.answer)&&a.answer.length===q.answer.length&&a.answer.every(x=>typeof x==='string'))||(q.type==='short'&&typeof a.answer==='string')))answers[id]={correct:a.correct,answer:q.type==='fill'?a.answer.map(x=>x.slice(0,1000)):q.type==='short'?a.answer.slice(0,20000):a.answer};}restored.session={ids:s.ids,index:s.index,answers,startedAt:Number.isSafeInteger(s.startedAt)&&s.startedAt>=0?s.startedAt:Date.now()};}return restored;}
function validPrefs(value){if(!value||!Array.isArray(value.excluded)||!value.excluded.every(x=>typeof x==='string'))throw Error('学习范围格式无效');return {excluded:[...new Set(value.excluded)].filter(k=>bank.some(q=>chapterKey(q)===k))};}
async function apiFetch(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{return await fetch(apiURL(path),{credentials:'same-origin',...options,signal:controller.signal,cache:'no-store'});}finally{clearTimeout(timer);}}
function storageNotice(){if(auth.needsLogin){document.getElementById('storage-warning').hidden=true;document.getElementById('storage-label').textContent='登录后读取共享数据库';return;}const label=document.getElementById('storage-label');if(label)label.textContent=requireServer&&!sync.ready?'等待连接共享数据库':sync.mode==='sqlite'?(sync.error?'数据库保存已暂停':sync.saving?'正在保存到数据库':'进度保存至部署数据库'):'进度保存在本设备';if(!sync.error){if(sync.mode==='sqlite'&&sync.ready)document.getElementById('storage-warning').hidden=true;return;}const warning=document.getElementById('storage-warning');warning.hidden=false;warning.innerHTML=`${esc(sync.error)} <button class="secondary" data-action="export">先导出本机备份</button> ${sync.blocked?'<button class="secondary" data-action="sync-reload">重新读取数据库</button>':'<button class="secondary" data-action="sync-retry">重试保存</button>'}`;}
function syncGate(){main.innerHTML=header('选择这台部署的学习进度','数据库当前为空，不会自动用浏览器记录覆盖或创建。','LOCAL DEPLOYMENT')+`<section class="panel"><h2>开始使用部署数据库</h2><p>之后的进度会保存到这台服务器的 SQLite 数据库。同一部署地址使用同一份进度，不是按浏览器自动区分的多用户系统。</p><p class="subtle">本浏览器有 ${Object.keys(sync.localCandidate?.state.records||{}).length} 条已有题目记录。请选择要写入数据库的起点。</p><div class="data-actions"><button class="primary" data-action="sync-import-local">使用本浏览器现有进度</button><button class="secondary" data-action="sync-fresh">从空白进度开始</button>${requireServer?'':'<button class="secondary" data-action="sync-browser">暂时仅用浏览器</button>'}<button class="secondary" data-action="export">先导出当前进度</button></div><p class="subtle">未选择前不会写入数据库；从空白开始不会删除已下载的备份文件。</p></section>`;}
async function initDatabase(force=false){const generation=auth.generation;if(sync.saving){toast('正在保存，请等待完成后重新读取。');return;}if(sync.initialized&&!force)return;sync.initialized=true;sync.mode='sqlite';sync.ready=false;sync.loading=true;render();try{const response=await apiFetch('/api/progress');if(generation!==auth.generation)return;if(response.status===401){requireLogin();throw Error('请先登录家庭学习空间');}if(!response.ok)throw Error('无法读取部署数据库');const data=await response.json();if(generation!==auth.generation)return;if(!Number.isSafeInteger(data.revision)||data.revision<0)throw Error('数据库版本无效');sync.revision=data.revision;if(data.state===null){sync.error='';sync.blocked=false;sync.localCandidate={state:JSON.parse(JSON.stringify(state)),preferences:JSON.parse(JSON.stringify(prefs))};sync.needsChoice=true;}else{const next=restoreState(data.state),nextPrefs=validPrefs(data.preferences);state=next;prefs=nextPrefs;sync.ready=true;sync.needsChoice=false;sync.error='';sync.blocked=false;sync.pending=null;try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(PREF,JSON.stringify(prefs));}catch(e){toast('数据库记录已读取，但浏览器备份不可用。');}}}catch(e){if(generation!==auth.generation)return;sync.error=auth.needsLogin?'请登录后读取数据库。':'数据库读取失败，已暂停数据库写入。当前仍可导出浏览器备份。';sync.blocked=true;}sync.loading=false;storageNotice();}
function queueSync(){if(sync.mode!=='sqlite'||!sync.ready)return;sync.pending=JSON.parse(JSON.stringify({state,preferences:prefs}));if(!sync.saving&&!sync.blocked&&!sync.error)flushSync();}
async function flushSync(){if(sync.saving||!sync.pending||sync.blocked||!sync.ready)return;sync.saving=true;storageNotice();try{while(sync.pending&&!sync.blocked){const snapshot=sync.pending;sync.pending=null;try{const response=await apiFetch('/api/progress',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...snapshot,revision:sync.revision})});if(response.status===401){sync.pending=sync.pending||snapshot;requireLogin(sync.pending);throw Error('登录已过期，待保存进度已保留，请重新登录。');}if(response.status===409){sync.pending=sync.pending||snapshot;sync.blocked=true;throw Error('其他页面已更新数据库，保存已暂停。请先导出本机备份，再重新读取数据库；不会自动覆盖。');}if(!response.ok)throw Error(`数据库保存失败（${response.status}），记录暂存在本浏览器。`);const result=await response.json();if(!Number.isSafeInteger(result.revision)||result.revision<=sync.revision){sync.blocked=true;throw Error('数据库返回版本无效，请重新读取数据库。');}sync.revision=result.revision;sync.error='';}catch(e){sync.pending=sync.pending||snapshot;sync.error=e.name==='AbortError'?'数据库保存超时，记录暂存在本浏览器，请重试。':e.message;break;}}}finally{sync.saving=false;storageNotice();if(auth.needsLogin||requireServer)render();}}
function chooseDatabase(mode){if(!sync.needsChoice)return;if(mode==='browser'){if(requireServer)return;sync.mode='local';sync.ready=false;sync.needsChoice=false;sync.error='';render();storageNotice();return;}if(mode==='fresh'&&!confirm('确定从空白进度开始？本浏览器现有进度将被替换，请先导出备份。'))return;state=mode==='fresh'?L.fresh():sync.localCandidate.state;prefs=mode==='fresh'?{excluded:[]}:sync.localCandidate.preferences;sync.ready=true;sync.needsChoice=false;sync.error='';sync.blocked=false;save();savePrefs();render();}

window.addEventListener?.('beforeunload',event=>{if(sync.mode==='sqlite'&&(sync.saving||sync.pending)){event.preventDefault();event.returnValue='';}});
async function boot(){
try{
const res=await fetch('./questions.json');if(!res.ok)throw Error('题库暂时无法加载');const data=await res.json();bank=Array.isArray(data)?data:data.questions;if(!Array.isArray(bank)||!bank.length)throw Error('题库为空');
try{const raw=localStorage.getItem(KEY);if(raw)state=restoreState(JSON.parse(raw));}catch(e){toast('部分本地记录无法读取，建议检查或导入备份。');}
try{const raw=localStorage.getItem(PREF);if(raw)prefs=validPrefs(JSON.parse(raw));}catch(e){toast('已学单元设置无法读取，已恢复全选。');}
await checkAPI();render();
}catch(err){main.innerHTML=header('题库还没有准备好','请稍后刷新重试。')+`<section class="panel"><p>${esc(err.message)}</p><button data-action="reload">重新加载</button></section>`;}
}
boot();
